//go:build !purego

package h264

//go:generate go run neon_gen.go

// NEON kernels (neon_arm64.s, generated by neon_gen.go — which needs macOS
// clang to assemble; the generated file is kept in the repo). They do no bounds
// checks; the wrappers in mc.go check the whole access once and fall back
// to the Go code when a block is too close to a buffer's end.

const haveNEON = true

//go:noescape
func neonLumaH(dst *byte, ds int, src *byte, ss int, w, h int)

//go:noescape
func neonLumaV(dst *byte, ds int, src *byte, ss int, w, h int)

//go:noescape
func neonLumaHV(dst *byte, ds int, src *byte, ss int, w, h int, tmp *int16)

//go:noescape
func neonChroma(dst *byte, ds int, src *byte, ss int, w, h int, a, b, c, d int)

//go:noescape
func neonLumaEdge(pix *byte, stride int, vert int, alpha, beta int, tc0 *int8, strong int)

//go:noescape
func neonChromaEdge(cb, cr *byte, stride, vert int, prm *[48]int8, strong int, gather, scatter *[64]byte)

//go:noescape
func neonIdct4Add(dst *byte, stride int, blk *[16]int32)
